/**
 * Visits every row a cursor-paged listing returns, following `nextCursor` until
 * the last page. For writes that must see a whole tenant, where reading only the
 * first page would silently leave the rest behind.
 */
export async function forEachPage<T>(
  listPage: (cursor: string | null) => Promise<Page<T>>,
  visit: (row: T) => Promise<unknown>,
): Promise<void> {
  let cursor: string | null = null;
  do {
    const page: Page<T> = await listPage(cursor);
    for (const row of page.items) {
      await visit(row);
    }
    cursor = page.nextCursor;
  } while (cursor !== null);
}

