  orgId: OrgId,
  project: Project,
): Promise<string | null> {
  if (isArchived(project)) {
    await removeFromIndex(orgId, "project", project.id);
    return null;
  }

  return searchRepo.upsertSearchDocument(
    orgId,
    "project",
    project.id,
    [project.name, project.description ?? ""].join("\n"),
    project.id,
  );
}

/**
 * Indexes an issue while it and its project are both live. Archiving the
 * project hides its issues whether or not the issues were archived too.
 */
