  orgId: OrgId,
  issue: Issue,
): Promise<string | null> {
  if (!(await isIssueSearchable(orgId, issue))) {
    await removeFromIndex(orgId, "issue", issue.id);
    return null;
  }

  return searchRepo.upsertSearchDocument(
