    issue === null ||
    !(await isIssueSearchable(orgId, issue))
  ) {
    await removeFromIndex(orgId, "comment", comment.id);
    return null;
  }

  return searchRepo.upsertSearchDocument(
    orgId,
    "comment",
    comment.id,
    comment.body,
    null,
  );
}

