/**
 * Rebuilds the search index for one organization; used after a bulk import or an index drift alarm.
 *
 * Must call (do not reimplement): indexIssue, indexComment, indexProject
 */
import { forEachPage } from "@/lib/pagination";
import { createLogger } from "@/lib/logger";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import {
  indexComment,
  indexIssue,
  indexProject,
} from "@/server/services/search-service";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { OrgId } from "@/types/common";

/** Rows read per page while walking the org's content. */
const PAGE_SIZE = 100;

const logger = createLogger("search-reindex-job");

/**
 * Walks every project, issue and comment in one tenant and re-writes its
 * document. Scoped to a single org on purpose: a full-fleet reindex is a
 * sequence of these, so one slow tenant cannot stall the rest.
 *
 * Archived rows are read too, and every page is walked rather than only the
 * first. The index writers decide which rows are searchable, so this job only
 * records the documents they keep. Once the walk is done, every other document
 * this org still holds is pruned, which leaves exactly what the rule allows.
 */
export async function runSearchReindexJob(orgId: OrgId): Promise<JobResult> {
  return runJob("search-reindex", async (result) => {
    const kept = new Set<string>();

    await forEachPage(
      (cursor) =>
        projectRepo.listProjects({
          orgId,
          limit: PAGE_SIZE,
          cursor,
          includeArchived: true,
        }),
      async (project) => {
        try {
          keepDocument(kept, await indexProject(orgId, project));
          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index project", {
            projectId: project.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      },
    );

    await forEachPage(
      (cursor) =>
        issueRepo.listIssues({
          orgId,
          limit: PAGE_SIZE,
          cursor,
          includeArchived: true,
        }),
      async (issue) => {
        try {
          keepDocument(kept, await indexIssue(orgId, issue));
          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index issue", {
            issueId: issue.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }

        await forEachPage(
          (cursor) =>
            commentRepo.listComments({
              orgId,
              issueId: issue.id,
              includeArchived: true,
              limit: PAGE_SIZE,
              cursor,
            }),
          async (comment) => {
            try {
              keepDocument(kept, await indexComment(orgId, comment));
              result.processed += 1;
            } catch (error) {
              result.failed += 1;
              logger.error("failed to index comment", {
                commentId: comment.id,
                reason: error instanceof Error ? error.message : String(error),
              });
            }
          },
        );
      },
    );

    const pruned = await searchRepo.pruneSearchDocuments(orgId, kept);
    logger.info("search index rebuilt", {
      orgId,
      kept: kept.size,
      pruned,
    });
  });
}

function keepDocument(kept: Set<string>, documentId: string | null): void {
  if (documentId !== null) kept.add(documentId);
}

