import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { eq } from "drizzle-orm";
import { getDb, searchIndex } from "@/server/db";
import { forEachPage } from "@/lib/pagination";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import { runSearchReindexJob } from "@/server/jobs/search-reindex-job";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { OrgId } from "@/types/common";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;
let lab: { id: string };

const projectInput = (orgId: OrgId, name: string, slug: string, key: string) => ({
  orgId,
  name,
  slug,
  key,
  description: null,
  visibility: "org" as const,
  leadId: null,
  color: "#6366f1",
  targetDate: null,
});

async function count(kind: "issue" | "comment" | "project", q: string): Promise<number> {
  const page = await searchService.search(tenant.actors.member, {
    orgId: tenant.org.id,
    q,
    kinds: [kind],
    limit: 25,
    cursor: null,
  });
  return page.total;
}

async function expectedIndexCount(orgId: OrgId): Promise<number> {
  let total = 0;
  const liveProjects = new Set<string>();
  await forEachPage(
    (cursor) => projectRepo.listProjects({ orgId, limit: 100, cursor, includeArchived: true }),
    async (p) => {
      if (p.archivedAt === null) {
        total += 1;
        liveProjects.add(p.id);
      }
    },
  );
  const liveIssues: string[] = [];
  const allIssues: { id: string; projectId: string; archivedAt: string | null }[] = [];
  await forEachPage(
    (cursor) => issueRepo.listIssues({ orgId, limit: 100, cursor, includeArchived: true }),
    async (i) => {
      allIssues.push(i);
      if (i.archivedAt === null && liveProjects.has(i.projectId)) {
        total += 1;
        liveIssues.push(i.id);
      }
    },
  );
  for (const issue of allIssues) {
    if (!liveIssues.includes(issue.id)) continue;
    await forEachPage(
      (cursor) => commentRepo.listComments({ orgId, issueId: issue.id as never, includeArchived: false, limit: 100, cursor }),
      async () => {
        total += 1;
      },
    );
  }
  return total;
}

let detach: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = searchService.registerSearchListeners();
  tenant = await createTenant("sfix", "growth");
  other = await createTenant("sfixo", "growth");
  lab = await projectService.createProject(
    tenant.actors.admin,
    projectInput(tenant.org.id, "Search Lab", "search-lab", "SLB"),
  );
});

afterAll(() => {
  detach();
  cleanup();
});

describe("search index follows the live-state rule", () => {
  it("drops an archived issue and its comments from search", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, lab.id as never, { title: "Alpha issue marker" }),
    );
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "Alpha comment marker",
      parentId: null,
      mentionedUserIds: [],
    });
    expect(await count("issue", "Alpha issue marker")).toBe(1);
    expect(await count("comment", "Alpha comment marker")).toBe(1);

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);

    expect(await count("issue", "Alpha issue marker")).toBe(0);
    expect(await count("comment", "Alpha comment marker")).toBe(0);
  });

  it("hides a project's content while archived, and restores the live parts", async () => {
    const open = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, lab.id as never, { title: "Beta issue marker" }),
    );
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: open.id,
      body: "Beta comment marker",
      parentId: null,
      mentionedUserIds: [],
    });
    const early = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, lab.id as never, { title: "Beta archived earlier" }),
    );
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: early.id,
      body: "Beta early comment",
      parentId: null,
      mentionedUserIds: [],
    });
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, early.id);

    expect(await count("project", "Search Lab")).toBe(1);
    expect(await count("issue", "Beta issue marker")).toBe(1);

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: lab.id as never,
      archiveIssues: false,
    });

    expect(await count("project", "Search Lab")).toBe(0);
    expect(await count("issue", "Beta issue marker")).toBe(0);
    expect(await count("comment", "Beta comment marker")).toBe(0);

    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: open.id,
      body: "Beta posted while archived",
      parentId: null,
      mentionedUserIds: [],
    });
    await issueService.updateIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: open.id,
      title: "Beta edited while archived",
    });
    expect(await count("comment", "Beta posted while archived")).toBe(0);
    expect(await count("issue", "Beta edited while archived")).toBe(0);

    await projectService.restoreProject(tenant.actors.admin, tenant.org.id, lab.id as never);

    expect(await count("project", "Search Lab")).toBe(1);
    expect(await count("issue", "Beta edited while archived")).toBe(1);
    expect(await count("comment", "Beta comment marker")).toBe(1);
    expect(await count("comment", "Beta posted while archived")).toBe(1);
    expect(await count("issue", "Beta archived earlier")).toBe(0);
    expect(await count("comment", "Beta early comment")).toBe(0);
  });

  it("keeps cascade-archived issues hidden after the project is restored", async () => {
    const gamma = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, lab.id as never, { title: "Gamma cascade issue" }),
    );
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: gamma.id,
      body: "Gamma cascade comment",
      parentId: null,
      mentionedUserIds: [],
    });
    expect(await count("issue", "Gamma cascade issue")).toBe(1);

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: lab.id as never,
      archiveIssues: true,
    });
    expect(await count("issue", "Gamma cascade issue")).toBe(0);
    expect(await count("issue", "Beta edited while archived")).toBe(0);

    await projectService.restoreProject(tenant.actors.admin, tenant.org.id, lab.id as never);

    expect(await count("project", "Search Lab")).toBe(1);
    expect(await count("issue", "Gamma cascade issue")).toBe(0);
    expect(await count("comment", "Gamma cascade comment")).toBe(0);
    expect(await count("issue", "Beta edited while archived")).toBe(0);
    expect(await count("comment", "Beta comment marker")).toBe(0);
  });

  it("reflects comment edits in the index", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, lab.id as never, { title: "Delta issue" }),
    );
    const comment = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "Delta original words",
      parentId: null,
      mentionedUserIds: [],
    });
    await commentService.updateComment(tenant.actors.member, {
      orgId: tenant.org.id,
      commentId: comment.id,
      body: "Delta revised words",
    });
    expect(await count("comment", "Delta revised words")).toBe(1);
    expect(await count("comment", "Delta original words")).toBe(0);
  });

  it("rebuilds a large workspace completely and prunes only its own stale rows", async () => {
    const bulk = await projectService.createProject(
      tenant.actors.admin,
      projectInput(tenant.org.id, "Bulk Lab", "bulk-lab", "BLB"),
    );

    const issueIds: string[] = [];
    for (let n = 1; n <= 230; n += 1) {
      const issue = await issueService.createIssue(
        tenant.actors.member,
        issueInput(tenant.org.id, bulk.id as never, { title: `Bulk issue number ${n}` }),
      );
      issueIds.push(issue.id);
    }
    const oldest = issueIds[0] as never;
    const newest = issueIds[issueIds.length - 1] as never;
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: oldest,
      body: "Bulk oldest comment",
      parentId: null,
      mentionedUserIds: [],
    });
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: newest,
      body: "Bulk newest comment",
      parentId: null,
      mentionedUserIds: [],
    });
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issueIds[1] as never);

    const deleted = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: newest,
      body: "Bulk deleted comment",
      parentId: null,
      mentionedUserIds: [],
    });
    await commentService.deleteComment(tenant.actors.member, {
      orgId: tenant.org.id,
      commentId: deleted.id,
    });

    // Simulate drift: wipe this org's rows, plant stale ones, and plant a row for the other tenant.
    getDb().delete(searchIndex).where(eq(searchIndex.orgId, tenant.org.id)).run();
    await searchRepo.upsertSearchDocument(tenant.org.id, "issue", "ghost-issue", "Ghost stale issue", null);
    await searchRepo.upsertSearchDocument(tenant.org.id, "comment", deleted.id, "Bulk deleted comment", null);
    await searchRepo.upsertSearchDocument(other.org.id, "issue", "other-ghost", "Other tenant stale", null);

    const otherIssue = await issueService.createIssue(
      other.actors.member,
      issueInput(other.org.id, other.project.id, { title: "Other tenant live" }),
    );
    const otherBefore = await searchRepo.countIndexed(other.org.id);

    const result = await runSearchReindexJob(tenant.org.id);
    expect(result.failed).toBe(0);

    expect(await count("issue", "Bulk issue number")).toBe(229);
    expect(await count("issue", "Ghost stale issue")).toBe(0);
    expect(await count("comment", "Bulk deleted comment")).toBe(0);
    expect(await count("comment", "Bulk oldest comment")).toBe(1);
    expect(await count("comment", "Bulk newest comment")).toBe(1);
    expect(await count("issue", "Bulk issue number 2")).toBe(1);
    expect(await count("issue", "Bulk issue number 1")).toBe(1);

    expect(await searchRepo.countIndexed(tenant.org.id)).toBe(await expectedIndexCount(tenant.org.id));

    expect(await searchRepo.countIndexed(other.org.id)).toBe(otherBefore);
    const otherHits = await searchService.search(other.actors.member, {
      orgId: other.org.id,
      q: "Other tenant",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(otherHits.total).toBe(1);
    expect(otherHits.items[0]).toMatchObject({ id: otherIssue.id });
  });
});

